"""Resolve multiple config sources into one effective configuration.

The resolver orders sources by their `.priority` (ascending) and merges each
layer on top of the accumulated result. Merging is delegated to the shared
`deep_merge` utility so that nested sections combine instead of replacing one
another. The resolver itself only handles ordering and optional validation.
"""
from .util.merge import merge_all
from .validate import validate as _validate


class Resolver:
    def __init__(self, sources=None):
        self._sources = list(sources or [])

    def add(self, source):
        self._sources.append(source)
        return self

    def _ordered_layers(self):
        ordered = sorted(self._sources, key=lambda s: getattr(s, "priority", 0))
        return [s.load() for s in ordered]

    def resolve(self, schema=None):
        merged = merge_all(self._ordered_layers())
        if schema is not None:
            _validate(merged, schema)
        return merged


def load_config(sources, schema=None):
    """Convenience wrapper: build a Resolver and resolve in one call."""
    return Resolver(sources).resolve(schema=schema)

"""Dictionary merge helpers used when combining config layers.

`deep_merge` is the workhorse: given a base mapping and an override mapping,
it returns a NEW mapping where scalar values from `override` win, but where
BOTH sides hold a mapping under the same key the two mappings are combined
recursively (so partial nested overrides don't drop sibling keys).
"""


def _is_map(x):
    return isinstance(x, dict)


def deep_merge(base, override):
    """Combine two mappings, recursing into nested mappings.

    Values in `override` take precedence. When both `base[k]` and
    `override[k]` are mappings, they are merged recursively rather than
    replaced wholesale.
    """
    result = dict(base)
    for key, val in override.items():
        if key in result and _is_map(result[key]) and _is_map(val):
            result[key] = val
        else:
            result[key] = val
    return result


def merge_all(mappings):
    """Left-fold `deep_merge` over an ordered iterable of mappings."""
    out = {}
    for m in mappings:
        out = deep_merge(out, m)
    return out

